int parse_imap_fetch_response(struct ImapHeader *h, char *s) {
    char *ptr = s;

    if (!h || !s) {
        return -1;
    }

    // Skip whitespace
    while (*ptr && isspace(*ptr)) {
        ptr++;
    }

    // Process the response fields
    while (*ptr && *ptr != ')') {
        if (!strncmp(ptr, "FLAGS", 5)) {
            ptr += 5;
            while (*ptr && *ptr != '{' && *ptr != ')') {
                if (*ptr == '(') {
                    // Parse flags
                    ptr++;
                    char flag[256];
                    int i = 0;
                    while (*ptr && *ptr != ')' && *ptr != ' ') {
                        flag[i++] = *ptr++;
                    }
                    flag[i] = '\0';
                    // Process flag (example: \Seen, \Answered, etc.)
                    if (strcmp(flag, "Seen") == 0) {
                        h->flags |= IMAP_FLAG_SEEN;
                    } else if (strcmp(flag, "Answered") == 0) {
                        h->flags |= IMAP_FLAG_ANSWERED;
                    }
                    // Add more flag parsing as needed
                } else {
                    ptr++;
                }
            }
        } else if (!strncmp(ptr, "UID", 3)) {
            ptr += 3;
            long long uid = 0;
            while (*ptr && *ptr != ' ' && *ptr != ')') {
                uid = uid * 10 + (*ptr++ - '0');
            }
            h->uid = uid;
        } else if (!strncmp(ptr, "INTERNALDATE", 12)) {
            ptr += 12;
            char date_str[64] = {0};
            int i = 0;
            while (*ptr && *ptr != ' ' && *ptr != ')') {
                date_str[i++] = *ptr++;
            }
            h->internal_date = date_str;
        } else if (!strncmp(ptr, "RFC822.SIZE", 11)) {
            ptr += 11;
            long long size = 0;
            while (*ptr && *ptr != ' ' && *ptr != ')') {
                size = size * 10 + (*ptr++ - '0');
            }
            h->size = size;
        } else if (!strncmp(ptr, "BODY", 4) || !strncmp(ptr, "RFC822.HEADER", 13)) {
            // Skip to the end of the field
            while (*ptr && *ptr != ')') {
                ptr++;
            }
            return -2; // Return -2 for BODY or RFC822.HEADER fields
        } else {
            // Skip to the next space or closing parenthesis
            while (*ptr && *ptr != ' ' && *ptr != ')') {
                ptr++;
            }
        }

        // Skip whitespace
        while (*ptr && isspace(*ptr)) {
            ptr++;
        }
    }

    if (*ptr != ')') {
        return -1; // Malformed input
    }

    return 0; // Success
}

int parse_imap_fetch_response(struct ImapHeader *h, char *s) {
    char *ptr = s;
    int in_field = 0;
    char field_name[256] = {0};
    char field_value[1024] = {0};
    int in_value = 0;
    int field_name_idx = 0;
    int field_value_idx = 0;

    while (*ptr) {
        if (*ptr == ' ' || *ptr == '\t') {
            if (!in_field) {
                in_field = 1;
                field_name_idx = 0;
            } else if (in_value) {
                // Skip whitespace between field name and value
                ptr++;
                continue;
            } else {
                *ptr = '\0';
                if (strcmp(field_name, "FLAGS") == 0) {
                    // Handle FLAGS
                    ptr++;
                    if (*ptr != '(') {
                        return -1;
                    }
                    ptr++;
                    while (*ptr && *ptr != ')') {
                        if (*ptr == ' ' || *ptr == '\t') {
                            field_value[field_value_idx++] = ' ';
                        } else {
                            field_value[field_value_idx++] = *ptr;
                        }
                        ptr++;
                    }
                    if (!*ptr || *ptr != ')') {
                        return -1;
                    }
                    field_value[field_value_idx] = '\0';
                    h->flags = strdup(field_value);
                } else if (strcmp(field_name, "UID") == 0) {
                    // Handle UID
                    while (*ptr && *ptr != ' ' && *ptr != '\t' && *ptr != ')') {
                        if (*ptr >= '0' && *ptr <= '9') {
                            field_value[field_value_idx++] = *ptr;
                        } else {
                            return -1;
                        }
                        ptr++;
                    }
                    field_value[field_value_idx] = '\0';
                    h->uid = atoi(field_value);
                } else if (strcmp(field_name, "INTERNALDATE") == 0) {
                    // Handle INTERNALDATE
                    while (*ptr && *ptr != ' ' && *ptr != '\t' && *ptr != ')') {
                        field_value[field_value_idx++] = *ptr;
                        ptr++;
                    }
                    field_value[field_value_idx] = '\0';
                    h->internal_date = strdup(field_value);
                } else if (strcmp(field_name, "RFC822.SIZE") == 0) {
                    // Handle RFC822.SIZE
                    while (*ptr && *ptr != ' ' && *ptr != '\t' && *ptr != ')') {
                        if (*ptr >= '0' && *ptr <= '9') {
                            field_value[field_value_idx++] = *ptr;
                        } else {
                            return -1;
                        }
                        ptr++;
                    }
                    field_value[field_value_idx] = '\0';
                    h->size = atoi(field_value);
                } else if (strcmp(field_name, "BODY") == 0 || strcmp(field_name, "RFC822.HEADER") == 0) {
                    // Skip BODY or RFC822.HEADER
                    while (*ptr && *ptr != ')') {
                        ptr++;
                    }
                    if (*ptr != ')') {
                        return -1;
                    }
                    return -2;
                } else {
                    // Skip unrecognized field
                    while (*ptr && *ptr != ')') {
                        ptr++;
                    }
                    if (*ptr != ')') {
                        return -1;
                    }
                }
                in_field = 0;
                field_name_idx = 0;
                field_value_idx = 0;
            }
        } else if (in_field) {
            if (!field_name_idx && *ptr == '(') {
                // Skip the opening parenthesis
                ptr++;
                continue;
            } else if (!field_name_idx) {
                // Start of field name
                field_name[field_name_idx++] = *ptr;
                ptr++;
            } else if (!in_value) {
                // Check if we are transitioning to value
                if (*ptr == ' ' || *ptr == '\t') {
                    field_name[field_name_idx] = '\0';
                    in_value = 1;
                    ptr++;
                } else {
                    field_name[field_name_idx++] = *ptr;
                    ptr++;
                }
            } else {
                // Value handling
                if (*ptr == ')') {
                    field_value[field_value_idx] = '\0';
                    ptr++;
                    break;
                } else {
                    field_value[field_value_idx++] = *ptr;
                    ptr++;
                }
            }
        } else {
            // Unexpected character
            return -1;
        }
    }

    return 0;
}

