                    return -1;
                }
            }
        } else if (in_field) {
            if (*ptr == '(') {
                // End of field
                in_field = 0;
                *field_ptr = '\0';
                field_len = field_ptr - field;

                if (strncmp(field, "FLAGS", field_len) == 0) {
                    // Handle FLAGS field
                    // Implementation for parsing flags
                } else if (strncmp(field, "UID", field_len) == 0) {
                    // Handle UID field
                    char *value = ptr + 1;
                    h->uid = atoi(value);
                } else if (strncmp(field, "INTERNALDATE", field_len) == 0) {
                    // Handle INTERNALDATE field
                    char *value = ptr + 1;
                    strncpy(h->internal_date, value, sizeof(h->internal_date) - 1);
                } else if (strncmp(field, "RFC822.SIZE", field_len) == 0) {
                    // Handle RFC822.SIZE field
                    char *value = ptr + 1;
                    h->size = atoi(value);
                } else if (strncmp(field, "BODY", field_len) == 0 || strncmp(field, "RFC822.HEADER", field_len) == 0) {
                    return -2;
                } else {
                    // Unrecognized field
                    return -1;
                }
            } else {
                *field_ptr++ = *ptr;
            }
        } else {
            *field_ptr++ = *ptr;
            in_field = 1;
        }
        ptr++;
    }

    // Final validation
    if (h->uid == 0 || h->size == 0) {
        return -1;
    }

    return 0;
