int parse_imap_fetch_response(struct ImapHeader *h, char *s) {
    char *ptr = s;

    while (*ptr) {
        // Skip whitespace
        while (*ptr && isspace((unsigned char)*ptr)) {
            ptr++;
        }

        if (!*ptr) {
            break;
        }

        // Parse known fields
        if (!strncmp(ptr, "FLAGS", 5)) {
            ptr += 5;
            // Parse flags (simplified example)
            while (*ptr && *ptr != ')') {
                ptr++;
            }
            if (*ptr == ')') {
                ptr++;
            }
        } else if (!strncmp(ptr, "UID", 3)) {
            ptr += 3;
            char *end;
            unsigned long uid = strtoul(ptr, &end, 10);
            if (end != ptr && *end == ' ') {
                h->uid = uid;
                ptr = end;
            } else {
                return -1;
            }
        } else if (!strncmp(ptr, "INTERNALDATE", 12)) {
            ptr += 12;
            // Parse internal date (example: "15-Oct-2023 12:34:56 +0000")
            char date_str[64];
            int i = 0;
            while (*ptr && *ptr != ' ' && i < sizeof(date_str) - 1) {
                date_str[i++] = *ptr++;
            }
            date_str[i] = '\0';
            h->internal_date = strdup(date_str);
            if (!h->internal_date) {
                return -1;
            }
        } else if (!strncmp(ptr, "RFC822.SIZE", 11)) {
            ptr += 11;
            char *end;
            unsigned long size = strtoul(ptr, &end, 10);
            if (end != ptr && *end == ' ') {
                h->size = size;
                ptr = end;
            } else {
                return -1;
            }
        } else if (!strncmp(ptr, "BODY", 4) || !strncmp(ptr, "RFC822.HEADER", 13)) {
            return -2;
